(function(){var root=document.getElementById('hoq-app');if(!root)return;var LW=270,IW=62,W=60,CW=196;var KEY='pmnet-hoq-v1',MAXN=12,MAXH=10;var RELS=[0,1,3,9],RSYM={0:'',1:'\u25BD',3:'\u25CB',9:'\u25CF'},RNAME={0:'No relationship',1:'Weak',3:'Medium',9:'Strong'};var ROOFS=[0,2,1,-1,-2],FSYM={'0':'','2':'++','1':'+','-1':'\u2212','-2':'\u2212\u2212'};var FNAME={'0':'No correlation','2':'Strong synergy','1':'Synergy','-1':'Trade-off','-2':'Strong trade-off'};var DIRS=['max','min','target'],DSYM={max:'\u25B2',min:'\u25BC',target:'\u25CE'},DNAME={max:'More is better',min:'Less is better',target:'Hit a target value'};var PRESETS={coffee:{label:'Coffee maker',needs:[['Coffee tastes great',5,3,4],['Brews quickly',4,4,3],['Easy to clean',4,2,4],['Stays hot for hours',3,3,3],['Runs quietly',2,3,2],['Affordable price',4,4,3]],hows:[['Brew water temperature','target','92 to 96 \u00B0C'],['Heater power','max','1500 W'],['Carafe heat retention','max','Above 70 \u00B0C for 4 h'],['Parts that detach for washing','max','5 parts, dishwasher safe'],['Noise while brewing','min','Under 45 dB'],['Unit manufacturing cost','min','$38']],rel:[[9,3,1,0,0,0],[1,9,0,0,0,0],[0,0,0,9,0,0],[0,1,9,0,0,0],[0,3,0,0,9,0],[0,3,3,3,1,9]],roof:[[0,1,1],[0,2,1],[1,4,-1],[1,5,-1],[2,5,-2],[3,5,-1],[4,5,-1]]},bank:{label:'Mobile banking app',needs:[['The app feels fast',5,3,4],['I can find what I need',4,3,3],['My money feels safe',5,4,4],['Payments go through right away',4,3,4],['It does not drain my battery',2,3,3],['I get help when something goes wrong',3,2,3]],hows:[['Screen load time','min','Under 1.5 s'],['Taps to reach top tasks','min','3 or fewer'],['Login and verification strength','max','2FA on every login'],['Payment confirmation time','min','Under 5 s'],['Background battery use','min','Under 2% per day'],['Support reply time','min','Under 2 min in chat']],rel:[[9,3,1,3,1,0],[1,9,0,0,0,1],[0,0,9,1,0,1],[3,0,1,9,0,0],[1,0,0,0,9,0],[0,3,0,0,0,9]],roof:[[0,2,-1],[1,2,-1],[0,3,1],[0,4,1],[2,3,-1],[1,5,1]]},blank:{label:'blank house',needs:[['',3,3,3],['',3,3,3],['',3,3,3]],hows:[['Feature A','max',''],['Feature B','max',''],['Feature C','max','']],rel:[],roof:[]}};var state,uid=1,undoSnap=null,statusTimer=null,pendingFocus=null;function nid(){return'k'+(uid++)}
function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
function rk(a,b){return a<b?a+'|'+b:b+'|'+a}
function needName(n){return n.text&&n.text.trim()?n.text.trim():'Untitled need'}
function howName(h){return h.text&&h.text.trim()?h.text.trim():'Untitled feature'}
function findNeed(id){for(var i=0;i<state.needs.length;i++)if(state.needs[i].id===id)return state.needs[i]}
function findHow(id){for(var i=0;i<state.hows.length;i++)if(state.hows[i].id===id)return state.hows[i]}
function fromPreset(name){var p=PRESETS[name],s={needs:[],hows:[],rel:{},roof:{}};p.needs.forEach(function(n){s.needs.push({id:nid(),text:n[0],imp:n[1],us:n[2],rv:n[3]})});p.hows.forEach(function(h){s.hows.push({id:nid(),text:h[0],dir:h[1],target:h[2]})});p.rel.forEach(function(row,i){row.forEach(function(v,j){if(v)s.rel[s.needs[i].id+'|'+s.hows[j].id]=v})});p.roof.forEach(function(r){s.roof[rk(s.hows[r[0]].id,s.hows[r[1]].id)]=r[2]});return s}
function save(){try{localStorage.setItem(KEY,JSON.stringify({s:state,u:uid}))}catch(e){}}
function restore(){try{var raw=localStorage.getItem(KEY);if(!raw)return!1;var d=JSON.parse(raw);if(!d||!d.s||!d.s.needs||!d.s.hows||!d.s.needs.length||!d.s.hows.length)return!1;state=d.s;state.rel=state.rel||{};state.roof=state.roof||{};uid=d.u||1000;return!0}catch(e){return!1}}
function compute(){var scores=state.hows.map(function(h){return state.needs.reduce(function(s,n){return s+n.imp*(state.rel[n.id+'|'+h.id]||0)},0)});var total=scores.reduce(function(a,b){return a+b},0);var pct=scores.map(function(s){return total?s/total*100:0});var maxPct=Math.max.apply(null,pct.concat([0]));var rank=scores.map(function(s){return 1+scores.filter(function(o){return o>s}).length});var order=state.hows.map(function(h,i){return i}).sort(function(a,b){return scores[b]-scores[a]});var top={};order.filter(function(i){return scores[i]>0}).slice(0,3).forEach(function(i){top[state.hows[i].id]=!0});return{scores:scores,total:total,pct:pct,maxPct:maxPct,rank:rank,order:order,top:top}}
function shell(){var opts=Object.keys(PRESETS).map(function(k){return'<option value="'+k+'">'+esc(k==='blank'?'Blank house':PRESETS[k].label)+'</option>'}).join('');root.innerHTML='<h2>Build your own House of Quality</h2>'+'<p class="hoq-intro">List what customers want, rate how much each need matters, then link it to the technical features that deliver it. The tool scores every feature so you can see where to focus. Click any cell in the grid or diamond in the roof to change it.</p>'+'<div class="hoq-toolbar">'+'<label>Start from <select data-act="preset" aria-label="Load an example"><option value="">Choose an example</option>'+opts+'</select></label>'+'<button type="button" class="hoq-btn" data-act="addneed">+ Customer need</button>'+'<button type="button" class="hoq-btn" data-act="addhow">+ Technical feature</button>'+'<span class="hoq-spacer"></span>'+'<button type="button" class="hoq-btn" data-act="csv">Download CSV</button>'+'<button type="button" class="hoq-btn primary" data-act="print">Print or save as PDF</button>'+'</div>'+'<div class="hoq-status" role="status" aria-live="polite"></div>'+'<div class="hoq-scroll"><div class="hoq-house-wrap"></div></div>'+'<section class="hoq-insights"></section>'}
function dots(n,type,label){var h='<div class="hoq-dots"><span class="lbl">'+label+'</span>';for(var k=1;k<=5;k++){h+='<button type="button" class="hoq-dot '+type+(k<=n[type]?' on':'')+'" data-act="'+type+'" data-id="'+n.id+'" data-v="'+k+'" data-fk="'+type+'-'+n.id+'-'+k+'" aria-pressed="'+(k===n[type])+'" aria-label="'+label+' rating for '+esc(needName(n))+': '+k+' of 5"></button>'}
return h+'</div>'}
function houseHTML(c){var hows=state.hows,needs=state.needs,n=hows.length;var tableW=LW+IW+n*W+CW,H=n*W/2,i,j;var h='<div class="hoq-house" style="width:'+tableW+'px">';h+='<div class="hoq-roofrow" style="min-height:'+Math.max(H,150)+'px">';h+='<div class="hoq-legend" style="width:'+(LW+IW)+'px">'+'<b>Relationship (grid)</b><div class="row"><span><span class="sym">\u25CF</span>Strong 9</span><span><span class="sym">\u25CB</span>Medium 3</span><span><span class="sym">\u25BD</span>Weak 1</span></div>'+'<b>Correlation (roof)</b><div class="row"><span><span class="sym pos">++</span>Strong synergy</span><span><span class="sym pos">+</span>Synergy</span></div>'+'<div class="row"><span><span class="sym neg">\u2212</span>Trade-off</span><span><span class="sym neg">\u2212\u2212</span>Strong trade-off</span></div>'+'</div>';h+='<div class="hoq-roof" style="width:'+(n*W)+'px">';if(n>=2){h+='<svg width="'+(n*W)+'" height="'+H+'" viewBox="0 0 '+(n*W)+' '+H+'" role="group" aria-label="Correlation roof between technical features">';h+='<polygon class="hoq-roof-bg" points="0,'+H+' '+(n*W/2)+',0 '+(n*W)+','+H+'"/>';for(i=0;i<n;i++)for(j=i+1;j<n;j++){var a=hows[i],b=hows[j],cx=(i+j+1)*W/2,cy=H-(j-i)*W/2,r=W/2-1.5;var v=state.roof[rk(a.id,b.id)]||0,cls=v>0?' pos':(v<0?' neg':'');h+='<g class="hoq-d'+cls+'" data-act="roof" data-a="'+a.id+'" data-b="'+b.id+'" data-fk="rf-'+a.id+'-'+b.id+'" tabindex="0" role="button" aria-label="'+esc(howName(a))+' and '+esc(howName(b))+': '+FNAME[String(v)]+'">'+'<title>'+esc(howName(a))+' \u2194 '+esc(howName(b))+': '+FNAME[String(v)]+'</title>'+'<polygon points="'+cx+','+(cy-r)+' '+(cx+r)+','+cy+' '+cx+','+(cy+r)+' '+(cx-r)+','+cy+'"/>'+'<text x="'+cx+'" y="'+cy+'" dy="0.36em" text-anchor="middle">'+FSYM[String(v)]+'</text></g>'}
h+='</svg>'}
h+='</div></div>';h+='<table class="hoq-grid" style="width:'+tableW+'px"><colgroup><col style="width:'+LW+'px"><col style="width:'+IW+'px">';for(i=0;i<n;i++)h+='<col style="width:'+W+'px">';h+='<col style="width:'+CW+'px"></colgroup><thead><tr class="hoq-head">';h+='<th class="hoq-corner" scope="col"><strong>Customer needs</strong><small>What customers want, in their own words</small></th>';h+='<th scope="col"><span class="hoq-vstatic">Importance (1 to 5)</span></th>';hows.forEach(function(hw){h+='<th scope="col" class="hoq-how'+(c.top[hw.id]?' is-top':'')+'"><div class="hoq-how-inner">'+(n>1?'<button type="button" class="hoq-x" data-act="delhow" data-id="'+hw.id+'" aria-label="Remove feature '+esc(howName(hw))+'" title="Remove this feature">\u00D7</button>':'<span></span>')+'<span class="hoq-vtext" contenteditable="true" spellcheck="false" role="textbox" aria-label="Technical feature name" data-act="howname" data-id="'+hw.id+'" data-fk="hn-'+hw.id+'">'+esc(hw.text)+'</span>'+'</div></th>'});h+='<th scope="col" class="hoq-comp-h"><strong>How you compare</strong><small>Customer rating, 1 poor to 5 excellent</small><div class="hoq-key"><span><i class="us"></i>You</span><span><i class="rv"></i>Competitor</span></div></th></tr>';h+='<tr><th colspan="2" scope="row" class="hoq-rowlabel">Direction of improvement</th>';hows.forEach(function(hw){h+='<td><button type="button" class="hoq-dir" data-act="dir" data-id="'+hw.id+'" data-fk="dir-'+hw.id+'" title="'+DNAME[hw.dir]+'" aria-label="Direction for '+esc(howName(hw))+': '+DNAME[hw.dir]+'">'+DSYM[hw.dir]+'</button></td>'});h+='<td class="hoq-note" style="padding:6px 10px">\u25B2 more is better, \u25BC less is better, \u25CE hit a target</td></tr></thead><tbody>';needs.forEach(function(nd){var behind=nd.rv>nd.us&&nd.imp>=4;h+='<tr><th scope="row" style="text-align:left"><div class="hoq-needwrap">'+'<input type="text" class="hoq-needname" data-act="needname" data-id="'+nd.id+'" data-fk="nn-'+nd.id+'" value="'+esc(nd.text)+'" placeholder="Describe a customer need" aria-label="Customer need">'+(needs.length>1?'<button type="button" class="hoq-x" data-act="delneed" data-id="'+nd.id+'" aria-label="Remove need '+esc(needName(nd))+'" title="Remove this need">\u00D7</button>':'')+'</div></th>';h+='<td class="hoq-imp"><select data-act="imp" data-id="'+nd.id+'" data-fk="imp-'+nd.id+'" aria-label="Importance of '+esc(needName(nd))+'">';for(var k=1;k<=5;k++)h+='<option value="'+k+'"'+(k===nd.imp?' selected':'')+'>'+k+'</option>';h+='</select></td>';hows.forEach(function(hw){var v=state.rel[nd.id+'|'+hw.id]||0;h+='<td'+(c.top[hw.id]?' class="is-topcol"':'')+'><button type="button" class="hoq-rel r'+v+'" data-act="rel" data-n="'+nd.id+'" data-h="'+hw.id+'" data-fk="rel-'+nd.id+'-'+hw.id+'" aria-label="'+esc(needName(nd))+' and '+esc(howName(hw))+': '+RNAME[v]+'" title="'+RNAME[v]+'">'+RSYM[v]+'</button></td>'});h+='<td class="hoq-comp'+(behind?' behind':'')+'">'+dots(nd,'us','You')+dots(nd,'rv','Competitor')+'</td></tr>'});h+='</tbody><tfoot>';h+='<tr><th colspan="2" scope="row" class="hoq-rowlabel">Target value</th>';hows.forEach(function(hw){h+='<td><textarea class="hoq-target" rows="3" data-act="target" data-id="'+hw.id+'" data-fk="tg-'+hw.id+'" placeholder="Set target" aria-label="Target value for '+esc(howName(hw))+'">'+esc(hw.target)+'</textarea></td>'});h+='<td class="hoq-note">Write the measurable goal for each feature, for example a time, a weight or a cost.</td></tr>';h+='<tr><th colspan="2" scope="row" class="hoq-rowlabel">Importance score</th>';hows.forEach(function(hw,idx){h+='<td class="hoq-score'+(c.top[hw.id]?' is-topcol':'')+'">'+c.scores[idx]+'</td>'});h+='<td class="hoq-note" rowspan="3">Each score adds up importance \u00D7 relationship strength (9, 3 or 1) down the column. The three highest are highlighted in orange.</td></tr>';h+='<tr><th colspan="2" scope="row" class="hoq-rowlabel">Relative weight</th>';hows.forEach(function(hw,idx){var hgt=c.maxPct?Math.max(c.pct[idx]/c.maxPct*100,0):0;h+='<td'+(c.top[hw.id]?' class="is-topcol"':'')+'><div class="hoq-barbox"><div class="hoq-barfill'+(c.top[hw.id]?' top':'')+'" style="height:'+hgt+'%"></div></div><span class="hoq-pct">'+Math.round(c.pct[idx])+'%</span></td>'});h+='</tr>';h+='<tr><th colspan="2" scope="row" class="hoq-rowlabel">Priority rank</th>';hows.forEach(function(hw,idx){h+='<td class="hoq-rank'+(c.top[hw.id]?' top':'')+'">'+(c.scores[idx]>0?'#'+c.rank[idx]:'\u2013')+'</td>'});h+='</tr></tfoot></table></div>';return h}
function li(html){return'<li>'+html+'</li>'}
function section(marker,title,items,empty){return'<div class="hoq-ins"><h4><i class="'+marker+'"></i>'+title+'</h4><ul>'+(items.length?items.join(''):'<li class="empty">'+empty+'</li>')+'</ul></div>'}
function renderInsights(c){c=c||compute();var hows=state.hows,needs=state.needs,lead;var ranked=c.order.filter(function(i){return c.scores[i]>0});if(!c.total){lead='Link at least one customer need to a technical feature to see your priorities.'}else{var t=ranked.slice(0,3).map(function(i){return'<strong>'+esc(howName(hows[i]))+'</strong>'});lead='Put most of your effort into '+t[0]+', which carries '+Math.round(c.pct[ranked[0]])+'% of the total weight';if(t.length===2)lead+=', followed by '+t[1]+'.';else if(t.length===3)lead+=', followed by '+t[1]+' and '+t[2]+'.';else lead+='.'}
var focus=ranked.slice(0,3).map(function(i,pos){return li('<strong>'+esc(howName(hows[i]))+'</strong>: score '+c.scores[i]+', '+Math.round(c.pct[i])+'% of the weight'+(hows[i].target?' (target: '+esc(hows[i].target)+')':''))});var half=Math.ceil(hows.length/2),trades=[];for(var a=0;a<hows.length;a++)for(var b=a+1;b<hows.length;b++){var v=state.roof[rk(hows[a].id,hows[b].id)]||0;if(v<0){var bothHigh=c.scores[a]>0&&c.scores[b]>0&&c.rank[a]<=half&&c.rank[b]<=half;trades.push({w:c.scores[a]+c.scores[b],html:li('<strong>'+esc(howName(hows[a]))+'</strong> and <strong>'+esc(howName(hows[b]))+'</strong> '+(v===-2?'pull strongly against each other.':'work against each other.')+(bothHigh?' Both rank high, so settle this trade-off early.':''))})}}
trades.sort(function(x,y){return y.w-x.w});var risk=[];needs.forEach(function(nd){var mx=0;hows.forEach(function(hw){mx=Math.max(mx,state.rel[nd.id+'|'+hw.id]||0)});if(mx===0)risk.push(li('Nothing in the design addresses <strong>'+esc(needName(nd))+'</strong>.'+(nd.imp>=4?' Customers rate it as very important.':'')));else if(mx===1)risk.push(li('<strong>'+esc(needName(nd))+'</strong> only has weak links. Add a feature that serves it directly.'));});var question=[];hows.forEach(function(hw,idx){if(c.scores[idx]===0)question.push(li('<strong>'+esc(howName(hw))+'</strong> does not serve any customer need. Link it to one or consider dropping it.'));});var gaps=needs.filter(function(nd){return nd.imp>=4&&nd.rv>nd.us}).map(function(nd){return li('Customers rate the competitor higher on <strong>'+esc(needName(nd))+'</strong> ('+nd.rv+' vs '+nd.us+'), and it has importance '+nd.imp+'.')});root.querySelector('.hoq-insights').innerHTML='<h3>What your house is telling you</h3><p class="hoq-lead">'+lead+'</p><div class="hoq-ins-grid">'+section('m-focus','Where to focus',focus,'No priorities yet. Click cells in the grid to link needs to features.')+section('m-trade','Trade-offs to resolve',trades.map(function(t){return t.html}),'No trade-offs recorded. Click a roof diamond to mark one.')+section('m-risk','Customer needs at risk',risk,'Every customer need has at least one medium or strong link.')+section('m-question','Features to question',question,'Every feature serves at least one customer need.')+section('m-gap','Competitive gaps',gaps,'You match or beat the competitor on every high-importance need.')+'</div>'}
function render(){var ae=document.activeElement,fk=pendingFocus||(ae&&root.contains(ae)?ae.getAttribute('data-fk'):null);pendingFocus=null;var c=compute();root.querySelector('.hoq-house-wrap').innerHTML=houseHTML(c);renderInsights(c);if(fk){var el=root.querySelector('[data-fk="'+fk+'"]');if(el)el.focus();}
save()}
function flash(msg,canUndo){var s=root.querySelector('.hoq-status');s.innerHTML=esc(msg)+(canUndo?'<button type="button" class="hoq-link" data-act="undo">Undo</button>':'');clearTimeout(statusTimer);statusTimer=setTimeout(function(){s.innerHTML=''},9000)}
function snapshot(){undoSnap=JSON.stringify(state)}
function selectAll(el){try{var r=document.createRange();r.selectNodeContents(el);var s=window.getSelection();s.removeAllRanges();s.addRange(r)}catch(e){}}
function downloadCSV(){var c=compute(),hows=state.hows,rows=[];rows.push(['Customer need','Importance','You (1-5)','Competitor (1-5)'].concat(hows.map(howName)));state.needs.forEach(function(nd){rows.push([needName(nd),nd.imp,nd.us,nd.rv].concat(hows.map(function(hw){return state.rel[nd.id+'|'+hw.id]||''})))});rows.push([]);rows.push(['Direction of improvement','','',''].concat(hows.map(function(hw){return DNAME[hw.dir]})));rows.push(['Target value','','',''].concat(hows.map(function(hw){return hw.target||''})));rows.push(['Importance score','','',''].concat(c.scores));rows.push(['Relative weight (%)','','',''].concat(c.pct.map(function(p){return p.toFixed(1)})));rows.push(['Priority rank','','',''].concat(c.rank.map(function(r,i){return c.scores[i]>0?r:''})));rows.push([]);rows.push(['Roof correlations']);rows.push(['Feature','Feature','Correlation']);for(var a=0;a<hows.length;a++)for(var b=a+1;b<hows.length;b++){var v=state.roof[rk(hows[a].id,hows[b].id)]||0;if(v)rows.push([howName(hows[a]),howName(hows[b]),FNAME[String(v)]]);}
var csv='\uFEFF'+rows.map(function(r){return r.map(function(x){x=String(x);return/[",\n;]/.test(x)?'"'+x.replace(/"/g,'""')+'"':x}).join(',')}).join('\r\n');try{var blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a2=document.createElement('a');a2.href=url;a2.download='house-of-quality.csv';document.body.appendChild(a2);a2.click();document.body.removeChild(a2);setTimeout(function(){URL.revokeObjectURL(url)},1000);flash('Downloaded house-of-quality.csv.')}catch(e){flash('The download could not start in this browser. Try Print or save as PDF instead.')}}
var FONT_URL='https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600;700&display=swap';var PRINT_CSS='@page{margin:12mm}'+'html,body{margin:0;padding:0;background:#fff}'+'body{-webkit-print-color-adjust:exact;print-color-adjust:exact}'+'.hoq-app{border:0!important;border-radius:0!important;padding:0!important;margin:0!important;max-width:none!important}'+'.hoq-app .hoq-toolbar,.hoq-app .hoq-status,.hoq-app .hoq-x,.hoq-app .hoq-intro{display:none!important}'+'.hoq-app .hoq-scroll{overflow:visible!important}'+'.hoq-app select{background-image:none!important;padding-right:8px!important;border-color:transparent!important}'+'.hoq-app h2{margin-bottom:14px!important}'+'.hoq-app .hoq-insights{break-before:page;page-break-before:always;border-top:0!important;margin-top:0!important;padding-top:0!important}'+'.hoq-app .hoq-ins{break-inside:avoid;page-break-inside:avoid}'+'.hoq-printfoot{font-family:"IBM Plex Sans",system-ui,sans-serif;font-size:11px;color:#5b6677;margin-top:18px}';function toolCSS(){var el=document.getElementById('hoq-style');if(el&&el.textContent)return el.textContent;var out=[];for(var i=0;i<document.styleSheets.length;i++){var rules;try{rules=document.styleSheets[i].cssRules}catch(e){continue}
if(!rules)continue;for(var j=0;j<rules.length;j++){if(rules[j].cssText.indexOf('.hoq-')!==-1)out.push(rules[j].cssText);}}
return out.join('\n')}
function printHouse(){render();var old=document.getElementById('hoq-print-frame');if(old)old.parentNode.removeChild(old);var fr=document.createElement('iframe');fr.id='hoq-print-frame';fr.setAttribute('aria-hidden','true');fr.tabIndex=-1;fr.title='Print';fr.style.cssText='position:fixed;right:0;bottom:0;width:0;height:0;border:0';document.body.appendChild(fr);var w=fr.contentWindow,d=w.document,clone=root.cloneNode(!0);clone.removeAttribute('id');var stamp=new Date().toLocaleDateString(undefined,{year:'numeric',month:'long',day:'numeric'});d.open();d.write('<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><title>House of Quality</title>'+'<link rel="stylesheet" href="'+FONT_URL+'"><style>'+toolCSS()+PRINT_CSS+'</style></head><body>'+clone.outerHTML+'<p class="hoq-printfoot">Created '+esc(stamp)+' with the free House of Quality builder at '+esc(location.hostname+location.pathname)+'</p></body></html>');d.close();var fired=!1;function go(){if(fired)return;fired=!0;var house=d.querySelector('.hoq-house');if(house){var hw=house.scrollWidth,hh=house.scrollHeight+70;var zP=Math.min(1,703/hw,964/hh),zL=Math.min(1,964/hw,703/hh);var landscape=zL>zP,z=landscape?zL:zP;var st=d.createElement('style');st.textContent='@page{size:'+(landscape?'landscape':'portrait')+'}';d.head.appendChild(st);if(z<1)house.style.zoom=z.toFixed(3);}
try{w.focus();w.print()}catch(e){window.print()}}
w.addEventListener('afterprint',function(){setTimeout(function(){if(fr.parentNode)fr.parentNode.removeChild(fr);},500)});if(d.fonts&&d.fonts.ready){d.fonts.ready.then(function(){setTimeout(go,150)})}
setTimeout(go,1500)}
function act(el){var a=el.getAttribute('data-act'),id=el.getAttribute('data-id'),x;if(a==='rel'){var key=el.getAttribute('data-n')+'|'+el.getAttribute('data-h'),cur=state.rel[key]||0,nx=RELS[(RELS.indexOf(cur)+1)%RELS.length];if(nx)state.rel[key]=nx;else delete state.rel[key];pendingFocus=el.getAttribute('data-fk');render()}else if(a==='roof'){var k=rk(el.getAttribute('data-a'),el.getAttribute('data-b')),cv=state.roof[k]||0,nv=ROOFS[(ROOFS.indexOf(cv)+1)%ROOFS.length];if(nv)state.roof[k]=nv;else delete state.roof[k];pendingFocus=el.getAttribute('data-fk');render()}else if(a==='dir'){x=findHow(id);x.dir=DIRS[(DIRS.indexOf(x.dir)+1)%DIRS.length];pendingFocus=el.getAttribute('data-fk');render()}else if(a==='us'||a==='rv'){x=findNeed(id);x[a]=+el.getAttribute('data-v');pendingFocus=el.getAttribute('data-fk');render()}else if(a==='delneed'){if(state.needs.length<2)return;snapshot();x=findNeed(id);state.needs=state.needs.filter(function(nd){return nd.id!==id});Object.keys(state.rel).forEach(function(k2){if(k2.split('|')[0]===id)delete state.rel[k2]});render();flash('Removed "'+needName(x)+'".',!0)}else if(a==='delhow'){if(state.hows.length<2)return;snapshot();x=findHow(id);state.hows=state.hows.filter(function(hw){return hw.id!==id});Object.keys(state.rel).forEach(function(k2){if(k2.split('|')[1]===id)delete state.rel[k2]});Object.keys(state.roof).forEach(function(k2){var p=k2.split('|');if(p[0]===id||p[1]===id)delete state.roof[k2]});render();flash('Removed "'+howName(x)+'".',!0)}else if(a==='addneed'){if(state.needs.length>=MAXN){flash('You can list up to '+MAXN+' customer needs. Remove one to add another.');return}
var nn={id:nid(),text:'',imp:3,us:3,rv:3};state.needs.push(nn);pendingFocus='nn-'+nn.id;render()}else if(a==='addhow'){if(state.hows.length>=MAXH){flash('You can list up to '+MAXH+' technical features. Remove one to add another.');return}
var nh={id:nid(),text:'New feature',dir:'max',target:''};state.hows.push(nh);pendingFocus='hn-'+nh.id;render();var ed=root.querySelector('[data-fk="hn-'+nh.id+'"]');if(ed)selectAll(ed);}else if(a==='undo'){if(undoSnap){state=JSON.parse(undoSnap);undoSnap=null;render();flash('Change undone.')}}else if(a==='csv'){downloadCSV()}else if(a==='print'){printHouse()}}
root.addEventListener('click',function(e){var el=e.target.closest('[data-act]');if(!el||!root.contains(el))return;var a=el.getAttribute('data-act');if(a==='needname'||a==='howname'||a==='target'||a==='imp'||a==='preset')return;act(el)});root.addEventListener('keydown',function(e){var el=e.target;if(el.getAttribute&&el.getAttribute('data-act')==='roof'&&(e.key==='Enter'||e.key===' ')){e.preventDefault();act(el);return}
if(el.getAttribute&&(el.getAttribute('data-act')==='howname'||el.getAttribute('data-act')==='needname')&&e.key==='Enter'){e.preventDefault();el.blur()}});root.addEventListener('input',function(e){var el=e.target,a=el.getAttribute&&el.getAttribute('data-act'),id=el.getAttribute&&el.getAttribute('data-id');if(a==='needname'){findNeed(id).text=el.value;renderInsights();save()}else if(a==='howname'){findHow(id).text=el.textContent.replace(/\s+/g,' ');renderInsights();save()}else if(a==='target'){findHow(id).target=el.value;renderInsights();save()}});root.addEventListener('paste',function(e){if(e.target.getAttribute&&e.target.getAttribute('data-act')==='howname'){e.preventDefault();var t=(e.clipboardData||window.clipboardData).getData('text').replace(/\s+/g,' ');document.execCommand('insertText',!1,t)}});root.addEventListener('change',function(e){var el=e.target,a=el.getAttribute('data-act');if(a==='imp'){findNeed(el.getAttribute('data-id')).imp=+el.value;pendingFocus=el.getAttribute('data-fk');render()}else if(a==='preset'&&el.value){var name=el.value;snapshot();state=fromPreset(name);el.value='';render();flash(name==='blank'?'Started a blank house.':'Loaded the '+PRESETS[name].label.toLowerCase()+' example.',!0)}});shell();if(!restore())state=fromPreset('coffee');render()})()